/// <reference types="vite/client" />

interface ImportMetaEnv {
  /** Public ingestion routing; never place an upload/auth token in a VITE_* variable. */
  readonly VITE_SENTRY_DSN?: string;
  readonly VITE_SENTRY_RELEASE?: string;
  readonly VITE_SENTRY_ENVIRONMENT?: string;
  readonly VITE_API_BASE_URL: string;
  readonly VITE_API_URL: string;
  readonly VITE_LOCAL_ONLY_MODE?: string;
  readonly VITE_REQUIRE_AUTH?: string;
  readonly VITE_DEV_SESSION_STORAGE?: 'local' | 'keychain';
  readonly VITE_TERMS_URL?: string;
  readonly VITE_PRIVACY_URL?: string;
  // AI substrate (dev convenience — never ship a production build with these set)
  readonly VITE_ANTHROPIC_API_KEY?: string;
  readonly VITE_OPENAI_API_KEY?: string;
  readonly VITE_DEEPSEEK_AI_API_KEY?: string;
  readonly VITE_DEEPSEEK_API_KEY?: string;
  /** DEV-only loopback broker for structured General Agent smoke tests. */
  readonly VITE_DRIFTING_AGENT_DEBUG_URL?: string;
  /** DEV-only project route claimed by the Agent debug renderer. */
  readonly VITE_DRIFTING_AGENT_DEBUG_PROJECT_ID?: string;
  /** DEV-only reduced context window for forcing compaction in headless tests. */
  readonly VITE_DRIFTING_AGENT_DEBUG_CONTEXT_WINDOW_TOKENS?: string;
  /** DEV-only read-result cap for forcing durable result paging. */
  readonly VITE_DRIFTING_AGENT_DEBUG_RESULT_BUDGET_CHARS?: string;
  /** Explicit switch for the simulator-only frontend debug renderer bridge. */
  readonly VITE_DRIFTING_FRONTEND_DEBUG?: '1';
  /** Defined at build time: '1' only in a local release-performance measurement bundle. */
  readonly VITE_DRIFTING_PERF_BUILD?: '1' | '';
  /** Lets a development build send crash reports, for acceptance against a local service. */
  readonly VITE_DRIFTING_CRASH_REPORTS_IN_DEV?: '1';
  /** Loopback daemon URL for frontend debug commands. */
  readonly VITE_DRIFTING_FRONTEND_DEBUG_URL?: string;
  /** Ephemeral local session token generated by `pnpm drifting frontend serve`. */
  readonly VITE_DRIFTING_FRONTEND_DEBUG_TOKEN?: string;
  /** Selects real Android CDP or the iOS renderer bridge without capability ambiguity. */
  readonly VITE_DRIFTING_FRONTEND_DEBUG_TRANSPORT?: 'android-cdp' | 'ios-renderer-bridge' | 'desktop-renderer-bridge';
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
